import re,subprocess
files=subprocess.check_output(['git','diff','--name-only','--','.skilled/skills/sk-code/sk-code-quality/'],text=True).split()
for f in files:
    d=subprocess.check_output(['git','diff','-U0','--',f],text=True)
    removed=[];added=[]
    for line in d.splitlines():
        if line.startswith('---') or line.startswith('+++'): continue
        if line.startswith('-'): removed.append(line[1:])
        elif line.startswith('+'): added.append(line[1:])
    rw=set(re.findall(r"[A-Za-z0-9_`./\-]+",' '.join(removed)))
    aw=set(re.findall(r"[A-Za-z0-9_`./\-]+",' '.join(added)))
    lost=sorted(w for w in rw-aw if len(w)>2)
    print(f, 'LOST TOKENS:', lost[:40])
PY"}

